import{z as l,x as i,o as r,c as p,q as A,j as B,D as t,d as E,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"收益的核算口径","description":"","frontmatter":{"title":"收益的核算口径","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-return-accounting.md","filePath":"quant/ap-return-accounting.md","lastUpdated":1791063341000}'),d={name:"quant/ap-return-accounting.md"};function m(u,a,_,D,c,h){const n=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=A('<h1 id="收益的核算口径" tabindex="-1">收益的核算口径 <a class="header-anchor" href="#收益的核算口径" aria-label="Permalink to &quot;收益的核算口径&quot;">​</a></h1><div class="epigraph"><p>同一本账可以报出不止一个「收益」：现金流切在哪一刻、按谁的钱加权、分红算不算再投，每一条约定都在改写数字本身；口径不是细节，是收益的定义。</p><footer>—— 据 CFA Institute, Global Investment Performance Standards（GIPS）的时间加权与金额加权口径整理</footer></div><p><a href="/quant/omm-map">上一课</a>把期权做市台收成一条可审计的链：报价、落账、分桶、限额、执行、漂移、事件、仲裁，验收标准是「数字从哪来、谁改过、依据哪条规则」三问有文件答案。本课程「账户绩效与费用」问的是这条链的另一端：账本最终要折叠成哪几个数，投资人与管理层才说得清这个账户干得怎么样。第一课的缺口最基本：<strong>「收益」这个数是怎么算出来的</strong>。不先钉口径，后面的费用、净值、比率与基准全都悬空。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个账户在一年内有申赎、分红、费用计提，「赚了多少」不再唯一。两个极端口径给出不同的数：时间加权把各子区间收益连乘，剔除现金进出时点的影响；金额加权按全部现金流的现值解一个内部收益率，恰恰保留时点。分红不再投与再投是两条曲线；毛收益与净收益之间隔着一张费用瀑布。口径不写死，两个账户的数字不可比，同一账户的两个月份也不可比，更谈不上审计。缺口是把「收益」定义成一组可执行的字段：子区间怎么切、收益怎么连、现金流归谁、毛净差记在哪。</p><p><span class="marginnote">数字实例：期初 100 万元，涨到 110 万后你追加 50 万，月末市值 165 万。若不切分子区间，毛算 \\((165-100)/100=65\\%\\)，把追加的 50 万当成了收益；先在申购点切开再算，真实业绩只有 \\(10\\%\\)。切分规则的差别，就是「65%」与「10%」的差别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先切分：在每个<strong>外部现金流</strong>发生的时点把区间切开，现金流在期初进账时，子区间收益为</p> \\[R_t=\\frac{V_t-V_{t-1}-F_t}{V_{t-1}}, \\]<p>\\(V\\) 是区间端点的市值，\\(F_t\\) 是外部现金流（申购为正、赎回为负）。时间加权收益是链接：</p> \\[R_{\\mathrm{TWR}}=\\prod_t (1+R_t)-1. \\]<p>金额加权收益 \\(r\\) 解</p> \\[\\sum_t \\frac{C_t}{(1+r)^t}=V_T, \\]<p>即把每笔投入与期末市值折现到同一起点。对数收益 \\(r_t=\\ln(V_t/V_{t-1})\\) 在时间上可加，是复算与连接的便利形式。分红视为对持有人的流出，除息后价值链连续；要报「分红再投」的累计净值，而不是除权缺口造成的假摔。最后，同一套子区间跑两遍——费前一遍、费后一遍——毛净差整段留给下一课的费用瀑布，不要把费用混进 \\(F_t\\)。</p><h3 id="谁的收益" tabindex="-1">谁的收益 <a class="header-anchor" href="#谁的收益" aria-label="Permalink to &quot;谁的收益&quot;">​</a></h3><p>TWR 回答「策略的效率」，MWR 回答「这笔钱实际经历了什么」，两者都是合法口径，对象不同。机制上 TWR 把申赎时点当噪音剔除，因为时点是投资人的选择，不是策略的选择；MWR 恰恰把时点当成主体。</p><p><span class="marginnote">直觉类比：TWR 像汽车仪表盘上的车速——衡量这台车本身跑多快，与你何时上车无关；MWR 像你这次行程的平均速度——中间停车吃饭、绕路接人全都算在你头上。评价司机看前者，评价这趟出行看后者。</span></p><p><span class="marginnote">一笔钱月初 100 万涨 50% 到 150 万，月中再申购 150 万，月末横盘：时间加权报 \\(1.5\\times 1.0-1=50\\%\\)；金额加权解 \\(100y^2+150y=300\\) 得约 \\(29\\%\\)——后进的钱没吃到第一段涨幅。同一账户同一个月，两个口径差 21 个百分点。</span></p>',18)),(r(),B(s,null,{default:t(()=>[o(n,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEDGER%5B%22%E9%80%90%E7%AC%94%E8%B4%A6%E6%9C%AC%E4%B8%8E%E4%BC%B0%E5%80%BC%22%5D%20--%3E%20CUT%5B%22%E6%8C%89%E5%A4%96%E9%83%A8%E7%8E%B0%E9%87%91%E6%B5%81%E5%88%87%E5%AD%90%E5%8C%BA%E9%97%B4%22%5D%0A%20%20CUT%20--%3E%20SEG%5B%22%E5%AD%90%E5%8C%BA%E9%97%B4%E6%94%B6%E7%9B%8A%20R_t%22%5D%0A%20%20SEG%20--%3E%20TWR%5B%22%E8%BF%9E%E4%B9%98%3A%20%E6%97%B6%E9%97%B4%E5%8A%A0%E6%9D%83%22%5D%0A%20%20CUT%20--%3E%20CF%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E5%BA%8F%E5%88%97%20C_t%22%5D%0A%20%20CF%20--%3E%20MWR%5B%22%E8%A7%A3%20IRR%3A%20%E9%87%91%E9%A2%9D%E5%8A%A0%E6%9D%83%22%5D%0A%20%20TWR%20--%3E%20REP%5B%22%E5%8F%A3%E5%BE%84%E5%A3%B0%E6%98%8E%E4%B8%8B%E7%9A%84%E6%94%B6%E7%9B%8A%E6%95%B0%22%5D%0A%20%20MWR%20--%3E%20REP%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("时间加权能成为产品评价的标准，是因为评价的对象是"),e("strong",null,"可复制的决策序列"),E("：把区间在现金流处切开再连乘，任何一段收益都不含「钱恰好在场」的运气，两个不同申购节奏的投资人面对同一条 TWR 曲线。金额加权则把时点计入主体，它是账户持有人体验的唯一忠实度量——第七课会用它对账。两条机制要求不同的算术：链接是乘法复合，跨账户汇总要用加权平均而不是把收益率相加；对数收益时间可加、截面上不可加权平均，算术收益恰好相反——混用两条加法规则，是绩效报告里最常见的静默错误，报表勾稽对不上多半死在这里。")],-1)),(r(),B(s,null,{default:t(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%94%B6%E7%9B%8A%E8%A6%81%E5%BE%80%E5%93%AA%E4%B8%AA%E6%96%B9%E5%90%91%E5%90%88%3F%22%7D%20--%3E%20T%5B%22%E8%B7%A8%E6%97%B6%E9%97%B4%3A%20%E6%9C%88%E8%BF%9E%E6%88%90%E5%B9%B4%22%5D%0A%20%20Q%20--%3E%20X%5B%22%E6%88%AA%E9%9D%A2%3A%20%E5%87%A0%E4%B8%AA%E8%B4%A6%E6%88%B7%E5%90%88%E6%88%90%E6%80%BB%E7%BB%84%E5%90%88%22%5D%0A%20%20T%20--%3E%20LOG%5B%22%E5%AF%B9%E6%95%B0%E6%94%B6%E7%9B%8A%3A%20%E7%9B%B4%E6%8E%A5%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20T%20--%3E%20MUL%5B%22%E6%88%96%E7%AE%97%E6%9C%AF%E6%94%B6%E7%9B%8A%3A%20%E8%BF%9E%E4%B9%98%22%5D%0A%20%20X%20--%3E%20AR%5B%22%E7%AE%97%E6%9C%AF%E6%94%B6%E7%9B%8A%3A%20%E6%8C%89%E9%87%91%E9%A2%9D%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%22%5D%0A%20%20LOG%20--%3E%20BAD%5B%22%E8%AF%AF%E7%94%A8%3A%20%E7%AE%97%E6%9C%AF%E6%94%B6%E7%9B%8A%E9%80%90%E6%9C%88%E7%9B%B8%E5%8A%A0%2C%20%E7%BB%93%E6%9E%9C%E5%81%8F%E5%A4%A7%22%5D%0A%20%20AR%20--%3E%20BAD2%5B%22%E8%AF%AF%E7%94%A8%3A%20%E5%AF%B9%E6%95%B0%E6%94%B6%E7%9B%8A%E6%8C%89%E6%9D%83%E9%87%8D%E5%B9%B3%E5%9D%87%2C%20%E5%8B%BE%E7%A8%BD%E4%B8%8D%E9%BD%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：先涨 10% 再跌 5%，不是 \\(10\\%-5\\%=5\\%\\)，而是 \\(1.10\\times 0.95-1=4.5\\%\\)。涨跌基数的不同让连乘结果永远偏离简单相加；把逐月收益率直接相加，是刚入行最容易犯、又最难被肉眼发现的错误。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只钉口径。市值 \\(V_t\\) 从哪来——盯市、模型价与停牌处理——是下一课净值构造的事；毛净差里各科目占多少，归费用分类课；收益数有多少抽样误差、能否当技能证据，留给评估单元的<a href="/quant/deflated-sharpe">放气夏普</a>。归因是另一门算术：<a href="/quant/brinson">Brinson 归因</a>与<a href="/quant/pf-attribution-deep">绩效归因的深化</a>都要求收益先有口径，否则配置与选择的分母本身在漂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>收益不是天赋的数，是一组口径字段：切分规则、连接方式、现金流归属、毛净分界。</li><li>时间加权剔除申赎时点，度量策略；金额加权保留时点，度量持有人体验。</li><li>对数收益时间可加、算术收益截面可加权平均；两条加法规则不可混用。</li><li>分红与除权要显式处理，报告「再投」口径，否则派息日会出现假摔。</li><li>毛净两遍同口径复算，差额整段交给费用瀑布，不混进外部现金流。</li><li>出处：据 CFA Institute, <em>Global Investment Performance Standards</em> 的时间加权与金额加权口径整理。</li></ul>',5))])}const T=l(d,[["render",m]]);export{C as __pageData,T as default};
